import 'package:flutter/material.dart';
import 'dashboard_service.dart';

class UpdatesPage extends StatefulWidget{const UpdatesPage({super.key});@override State<UpdatesPage> createState()=>_UpdatesPageState();}
class _UpdatesPageState extends State<UpdatesPage>{final s=DashboardService();bool loading=true;String? error;List items=[];@override void initState(){super.initState();load();}Future<void>load()async{try{final d=await s.notifications();final n=d['notifications'];if(mounted)setState((){items=n is List?n:[];loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('School Updates',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),if(items.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(20),child:Text('No new updates'))),...items.asMap().entries.map((e)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:Duration(milliseconds:250+e.key*60),builder:(ctx,v,child)=>Opacity(opacity:v,child:Transform.translate(offset:Offset(0,12*(1-v)),child:child)),child:Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.notifications_active)),title:Text('${e.value['title']??'School update'}'),subtitle:Text('${e.value['message']??''}')))))]));}}
